package com.esn.smp.gameplay;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;
public final class Teleports implements CommandExecutor{
 private final JavaPlugin plugin;private final Map<UUID,UUID> requests=new HashMap<>();private final Map<UUID,Long> cooldown=new HashMap<>();private final Map<UUID,Location> back=new HashMap<>();
 public Teleports(JavaPlugin p){plugin=p;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;String n=c.getName().toLowerCase();if(n.equals("tpa")||n.equals("tpahere")){if(a.length<1){p.sendMessage(ChatColor.RED+"/"+n+" <player>");return true;}Player t=Bukkit.getPlayerExact(a[0]);if(t==null||t==p){p.sendMessage(ChatColor.RED+"Player not found.");return true;}requests.put(t.getUniqueId(),p.getUniqueId());t.sendMessage(ChatColor.GOLD+p.getName()+" sent a teleport request. /tpaccept or /tpdeny");p.sendMessage(ChatColor.GREEN+"Teleport request sent.");return true;}if(n.equals("tpaccept")){UUID u=requests.remove(p.getUniqueId());Player r=u==null?null:Bukkit.getPlayer(u);if(r==null){p.sendMessage(ChatColor.RED+"No active request.");return true;}long now=System.currentTimeMillis();if(cooldown.getOrDefault(r.getUniqueId(),0L)>now){r.sendMessage(ChatColor.RED+"Teleport is on cooldown.");return true;}Location old=r.getLocation().clone();r.sendMessage(ChatColor.YELLOW+"Teleporting in 3 seconds. Don't move.");plugin.getServer().getScheduler().runTaskLater(plugin,()->{if(!r.isOnline())return;back.put(r.getUniqueId(),old);r.teleport(p.getLocation());cooldown.put(r.getUniqueId(),System.currentTimeMillis()+15000);r.sendMessage(ChatColor.GREEN+"Teleported to "+p.getName()+".");},60L);return true;}if(n.equals("tpdeny")){requests.remove(p.getUniqueId());p.sendMessage(ChatColor.YELLOW+"Request denied.");return true;}if(n.equals("back")){Location b=back.get(p.getUniqueId());if(b==null)p.sendMessage(ChatColor.RED+"No previous location.");else{Location old=p.getLocation().clone();p.teleport(b);back.put(p.getUniqueId(),old);}return true;}return true;}
}
